-- Single-use, email-bound invitations. Existing member codes remain compatible.
BEGIN;
CREATE TABLE public.user_invitations (
  code text PRIMARY KEY CHECK (code ~ '^[A-F0-9]{16}$'),
  invited_by uuid NOT NULL REFERENCES public.profiles(id),
  recipient_email text NOT NULL CHECK (recipient_email = lower(trim(recipient_email))),
  created_at timestamptz NOT NULL DEFAULT now(),
  used_at timestamptz,
  used_by uuid REFERENCES auth.users(id) DEFERRABLE INITIALLY DEFERRED,
  CHECK ((used_at IS NULL) = (used_by IS NULL))
);
CREATE UNIQUE INDEX user_invitations_pending_recipient
  ON public.user_invitations(invited_by, recipient_email) WHERE used_at IS NULL;
ALTER TABLE public.user_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own invitations" ON public.user_invitations
  FOR SELECT TO authenticated USING (invited_by = auth.uid());
REVOKE ALL ON public.user_invitations FROM anon, authenticated;
GRANT SELECT ON public.user_invitations TO authenticated;

CREATE FUNCTION public.issue_user_invitation(p_email text)
RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_email text := lower(trim(p_email)); v_code text; v_owner uuid := auth.uid();
BEGIN
  IF v_owner IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Email inválido';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE lower(email) = v_email) THEN
    RAISE EXCEPTION 'Este email já tem conta. Usa a opção de entrar.';
  END IF;
  -- Serialize creation for the same inviter/recipient pair, including concurrent clicks.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_owner::text || ':' || v_email, 0));
  SELECT code INTO v_code FROM public.user_invitations
    WHERE invited_by = v_owner AND recipient_email = v_email AND used_at IS NULL;
  IF NOT FOUND THEN
    LOOP
      v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.user_invitations WHERE code = v_code)
        AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE upper(referral_code) = v_code)
        AND NOT EXISTS (SELECT 1 FROM public.mvp_candidates WHERE upper(access_code) = v_code);
    END LOOP;
    INSERT INTO public.user_invitations(code, invited_by, recipient_email)
      VALUES (v_code, v_owner, v_email);
  END IF;
  RETURN json_build_object('code', v_code);
END $$;
REVOKE ALL ON FUNCTION public.issue_user_invitation(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.issue_user_invitation(text) TO authenticated;

-- Preserve the deployed legacy validator rather than replacing its implementation.
ALTER FUNCTION public.validate_mvp_access_code(text) RENAME TO validate_legacy_mvp_access_code;
REVOKE ALL ON FUNCTION public.validate_legacy_mvp_access_code(text) FROM PUBLIC, anon, authenticated;
CREATE FUNCTION public.validate_mvp_access_code(p_code text)
RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_invite public.user_invitations%ROWTYPE;
BEGIN
  SELECT * INTO v_invite FROM public.user_invitations WHERE code = upper(trim(p_code));
  IF FOUND THEN
    IF v_invite.used_at IS NOT NULL THEN
      RETURN json_build_object('valid', false, 'error', 'Este convite já foi utilizado');
    END IF;
    RETURN json_build_object('valid', true, 'single_use', true);
  END IF;
  RETURN public.validate_legacy_mvp_access_code(p_code);
END $$;
REVOKE ALL ON FUNCTION public.validate_mvp_access_code(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_mvp_access_code(text) TO anon, authenticated;

-- Consume inside the auth-user transaction, before the existing profile gate.
-- A failed signup rolls back consumption; row locks prevent two accounts reusing it.
CREATE FUNCTION public.consume_user_invitation_on_signup()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_code text; v_invite public.user_invitations%ROWTYPE; v_ref text;
BEGIN
  v_code := upper(trim(coalesce(nullif(NEW.raw_user_meta_data->>'access_code', ''), NEW.raw_user_meta_data->>'ref', '')));
  SELECT * INTO v_invite FROM public.user_invitations WHERE code = v_code FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  IF v_invite.used_at IS NOT NULL THEN RAISE EXCEPTION 'Este convite já foi utilizado'; END IF;
  IF lower(trim(NEW.email)) IS DISTINCT FROM v_invite.recipient_email THEN
    RAISE EXCEPTION 'Este convite pertence a outro email';
  END IF;
  SELECT referral_code INTO v_ref FROM public.profiles WHERE id = v_invite.invited_by;
  IF v_ref IS NULL THEN RAISE EXCEPTION 'Convite indisponível'; END IF;
  UPDATE public.user_invitations SET used_at = now(), used_by = NEW.id WHERE code = v_code;
  -- Retain the original token for audit and pass the verified inviter to the existing gate.
  NEW.raw_user_meta_data := coalesce(NEW.raw_user_meta_data, '{}'::jsonb)
    || jsonb_build_object('invitation_code', v_code, 'access_code', v_ref, 'ref', v_ref);
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.consume_user_invitation_on_signup() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER consume_user_invitation_before_signup BEFORE INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.consume_user_invitation_on_signup();
COMMIT;

-- MVP invitation delegation is separate from administrator/moderator roles.
CREATE TABLE public.invitation_permissions (
 user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 granted_by uuid NOT NULL REFERENCES public.profiles(id),
 granted_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.invitation_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own or admin invitation permissions" ON public.invitation_permissions
 FOR SELECT TO authenticated USING (user_id = (select auth.uid()) OR public.has_role((select auth.uid()), 'admin'));
REVOKE ALL ON public.invitation_permissions FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.invitation_permissions TO authenticated;
CREATE FUNCTION public.can_issue_user_invitation(p_user_id uuid DEFAULT auth.uid())
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
 SELECT p_user_id IS NOT NULL AND (
 public.has_role(p_user_id, 'admin') OR EXISTS (SELECT 1 FROM public.invitation_permissions WHERE user_id = p_user_id));
$$;
REVOKE ALL ON FUNCTION public.can_issue_user_invitation(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_issue_user_invitation(uuid) TO authenticated;
CREATE FUNCTION public.set_invitation_permission(p_email text, p_allowed boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_user uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN
   RAISE EXCEPTION 'Só o administrador pode gerir autorizações.' USING ERRCODE = '42501';
 END IF;
 SELECT id INTO v_user FROM public.profiles WHERE lower(trim(email)) = lower(trim(p_email));
 IF v_user IS NULL THEN RAISE EXCEPTION 'Este email ainda não tem uma conta Yamilook.'; END IF;
 IF public.has_role(v_user, 'admin') THEN RAISE EXCEPTION 'O administrador já tem esta permissão.'; END IF;
 IF p_allowed THEN
   INSERT INTO public.invitation_permissions(user_id, granted_by) VALUES (v_user, auth.uid())
   ON CONFLICT (user_id) DO UPDATE SET granted_by = auth.uid(), granted_at = now();
 ELSE
   DELETE FROM public.invitation_permissions WHERE user_id = v_user;
 END IF;
END $$;
CREATE FUNCTION public.list_invitation_permissions()
RETURNS TABLE(email text, granted_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN
   RAISE EXCEPTION 'Só o administrador pode gerir autorizações.' USING ERRCODE = '42501';
 END IF;
 RETURN QUERY SELECT p.email, ip.granted_at FROM public.invitation_permissions ip
 JOIN public.profiles p ON p.id = ip.user_id ORDER BY ip.granted_at DESC;
END $$;
REVOKE ALL ON FUNCTION public.set_invitation_permission(text,boolean), public.list_invitation_permissions() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_invitation_permission(text,boolean), public.list_invitation_permissions() TO authenticated;
CREATE OR REPLACE FUNCTION public.issue_user_invitation(p_email text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_email text := lower(trim(p_email)); v_code text; v_owner uuid := auth.uid();
BEGIN
  IF NOT public.can_issue_user_invitation(v_owner) THEN RAISE EXCEPTION 'Só o administrador ou uma pessoa autorizada pode enviar convites no MVP.' USING ERRCODE = '42501'; END IF;
  IF v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Email inválido';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE lower(email) = v_email) THEN
    RAISE EXCEPTION 'Este email já tem conta. Usa a opção de entrar.';
  END IF;
  -- Serialize creation for the same inviter/recipient pair, including concurrent clicks.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_owner::text || ':' || v_email, 0));
  SELECT code INTO v_code FROM public.user_invitations
    WHERE invited_by = v_owner AND recipient_email = v_email AND used_at IS NULL;
  IF NOT FOUND THEN
    LOOP
      v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.user_invitations WHERE code = v_code)
        AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE upper(referral_code) = v_code)
        AND NOT EXISTS (SELECT 1 FROM public.mvp_candidates WHERE upper(access_code) = v_code);
    END LOOP;
    INSERT INTO public.user_invitations(code, invited_by, recipient_email)
      VALUES (v_code, v_owner, v_email);
  END IF;
  RETURN json_build_object('code', v_code);
END $function$;

CREATE OR REPLACE FUNCTION public.validate_legacy_mvp_access_code(p_code text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_candidate RECORD; v_member RECORD;
BEGIN
  -- código de convite de um membro (multi-uso)
  SELECT id, display_name INTO v_member FROM public.profiles
   WHERE upper(referral_code) = upper(trim(p_code)) AND public.can_issue_user_invitation(id) LIMIT 1;
  IF FOUND THEN
    RETURN json_build_object('valid', true, 'referral', true, 'member_name', v_member.display_name);
  END IF;

  -- código MVP clássico (uso único, emitido por admin)
  SELECT * INTO v_candidate FROM public.mvp_candidates WHERE access_code = upper(trim(p_code));
  IF NOT FOUND THEN
    RETURN json_build_object('valid', false, 'error', 'Código inválido');
  END IF;
  IF v_candidate.status != 'approved' THEN
    RETURN json_build_object('valid', false, 'error', 'Código não está ativo');
  END IF;
  IF v_candidate.code_used THEN
    RETURN json_build_object('valid', false, 'error', 'Este código já foi utilizado');
  END IF;
  RETURN json_build_object('valid', true, 'candidate_id', v_candidate.id,
    'full_name', v_candidate.full_name, 'email', v_candidate.email);
END $function$;

CREATE OR REPLACE FUNCTION public.consume_user_invitation_on_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_code text; v_invite public.user_invitations%ROWTYPE; v_ref text;
BEGIN
  v_code := upper(trim(coalesce(nullif(NEW.raw_user_meta_data->>'access_code', ''), NEW.raw_user_meta_data->>'ref', '')));
  SELECT * INTO v_invite FROM public.user_invitations WHERE code = v_code FOR UPDATE;
  IF NOT FOUND THEN
    IF coalesce((public.validate_legacy_mvp_access_code(v_code)->>'valid')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'YAMILOOK_MVP_ONLY: é necessário um convite autorizado';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT public.can_issue_user_invitation(v_invite.invited_by) THEN
    RAISE EXCEPTION 'Este convite já não está autorizado';
  END IF;
  IF v_invite.used_at IS NOT NULL THEN RAISE EXCEPTION 'Este convite já foi utilizado'; END IF;
  IF lower(trim(NEW.email)) IS DISTINCT FROM v_invite.recipient_email THEN
    RAISE EXCEPTION 'Este convite pertence a outro email';
  END IF;
  SELECT referral_code INTO v_ref FROM public.profiles WHERE id = v_invite.invited_by;
  IF v_ref IS NULL THEN RAISE EXCEPTION 'Convite indisponível'; END IF;
  UPDATE public.user_invitations SET used_at = now(), used_by = NEW.id WHERE code = v_code;
  -- Retain the original token for audit and pass the verified inviter to the existing gate.
  NEW.raw_user_meta_data := coalesce(NEW.raw_user_meta_data, '{}'::jsonb)
    || jsonb_build_object('invitation_code', v_code, 'access_code', v_ref, 'ref', v_ref);
  RETURN NEW;
END $function$;

-- Pending invitations are also rejected when the issuer's authorization is removed.
CREATE OR REPLACE FUNCTION public.validate_mvp_access_code(p_code text)
RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_invite public.user_invitations%ROWTYPE;
BEGIN
 SELECT * INTO v_invite FROM public.user_invitations WHERE code = upper(trim(p_code));
 IF FOUND THEN
   IF v_invite.used_at IS NOT NULL THEN RETURN json_build_object('valid', false, 'error', 'Este convite já foi utilizado'); END IF;
   IF NOT public.can_issue_user_invitation(v_invite.invited_by) THEN
     RETURN json_build_object('valid', false, 'error', 'Este convite já não está autorizado');
   END IF;
   RETURN json_build_object('valid', true, 'single_use', true);
 END IF;
 RETURN public.validate_legacy_mvp_access_code(p_code);
END $$;

-- Each visible browser renews its own lease; server timestamps prevent stale online flags.
CREATE SCHEMA IF NOT EXISTS private;
CREATE TABLE private.online_presence_leases (
 user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 client_id uuid NOT NULL,
 seen_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY (user_id, client_id)
);
ALTER TABLE private.online_presence_leases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.online_presence_leases FROM PUBLIC, anon, authenticated;
CREATE INDEX online_presence_expiry ON private.online_presence_leases(seen_at);

CREATE FUNCTION private.enforce_online_presence()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
 NEW.is_online := NEW.show_online_status IS DISTINCT FROM false AND EXISTS (
   SELECT 1 FROM private.online_presence_leases l
   WHERE l.user_id = NEW.id AND l.seen_at > now() - interval '2 minutes'
 );
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.enforce_online_presence() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER enforce_online_presence BEFORE INSERT OR UPDATE OF is_online, show_online_status
ON public.profiles FOR EACH ROW EXECUTE FUNCTION private.enforce_online_presence();

CREATE FUNCTION public.renew_online_presence(p_client_id uuid, p_active boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
 IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 IF p_client_id IS NULL OR p_active IS NULL THEN RAISE EXCEPTION 'Invalid presence'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_user::text, 0));
 IF p_active THEN
   INSERT INTO private.online_presence_leases(user_id,client_id,seen_at)
     VALUES(v_user,p_client_id,now())
     ON CONFLICT(user_id,client_id) DO UPDATE SET seen_at=now();
 ELSE
   DELETE FROM private.online_presence_leases WHERE user_id=v_user AND client_id=p_client_id;
 END IF;
 -- The trigger computes the flag from all active devices and the privacy preference.
 UPDATE public.profiles SET is_online=false, last_seen=now() WHERE id=v_user;
END $$;
REVOKE ALL ON FUNCTION public.renew_online_presence(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.renew_online_presence(uuid,boolean) TO authenticated;

CREATE FUNCTION private.expire_online_presence()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
 DELETE FROM private.online_presence_leases WHERE seen_at <= now()-interval '2 minutes';
 UPDATE public.profiles p SET is_online=false
 WHERE p.is_online AND (p.show_online_status = false OR NOT EXISTS (
   SELECT 1 FROM private.online_presence_leases l WHERE l.user_id=p.id AND l.seen_at>now()-interval '2 minutes'
 ));
END $$;
REVOKE ALL ON FUNCTION private.expire_online_presence() FROM PUBLIC, anon, authenticated;
-- Remove legacy flags immediately without inventing a new last-seen timestamp.
SELECT private.expire_online_presence();
SELECT cron.schedule('expire-yamilook-online-presence', '* * * * *', 'SELECT private.expire_online_presence()');

-- Full profiles belong to the owner and administrators; social reads use a whitelist.
CREATE OR REPLACE VIEW public.public_profiles WITH (security_barrier=true) AS
SELECT p.id,p.display_name,p.username,p.avatar_url,p.bio,p.level,
 (coalesce(p.show_online_status,true) AND coalesce(p.is_online,false)
  AND p.last_seen > now()-interval '2 minutes') AS is_online,
 CASE WHEN p.show_last_seen IS DISTINCT FROM false THEN p.last_seen ELSE NULL END AS last_seen,
 p.status_message,p.created_at,p.updated_at,p.is_verified,p.is_creator,p.founder_number,
 p.profile_theme_color,p.show_online_status,p.show_last_seen,p.show_read_receipts,
 p.show_typing_indicators,p.photos_visibility
FROM public.profiles p;
-- This deliberately privileged view exposes only this fixed whitelist, never p.*.
REVOKE ALL ON public.public_profiles FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.public_profiles TO anon,authenticated;
-- Restricted profile rows must not be broadcast to social presence subscribers.
CREATE TABLE public.profile_presence (
 id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
 is_online boolean NOT NULL DEFAULT false,
 last_seen timestamptz,
 show_online_status boolean NOT NULL DEFAULT true,
 show_last_seen boolean NOT NULL DEFAULT true,
 show_read_receipts boolean NOT NULL DEFAULT true,
 show_typing_indicators boolean NOT NULL DEFAULT true
);
ALTER TABLE public.profile_presence ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read safe presence" ON public.profile_presence FOR SELECT TO authenticated USING (true);
REVOKE ALL ON public.profile_presence FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.profile_presence TO authenticated;
CREATE FUNCTION private.publish_safe_profile_presence()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO public.profile_presence(id,is_online,last_seen,show_online_status,show_last_seen,show_read_receipts,show_typing_indicators)
 VALUES (NEW.id,coalesce(NEW.is_online,false) AND coalesce(NEW.show_online_status,true),
 CASE WHEN NEW.show_last_seen IS DISTINCT FROM false THEN NEW.last_seen ELSE NULL END,
 coalesce(NEW.show_online_status,true),coalesce(NEW.show_last_seen,true),
 coalesce(NEW.show_read_receipts,true),coalesce(NEW.show_typing_indicators,true))
 ON CONFLICT(id) DO UPDATE SET is_online=excluded.is_online,last_seen=excluded.last_seen,
 show_online_status=excluded.show_online_status,show_last_seen=excluded.show_last_seen,
 show_read_receipts=excluded.show_read_receipts,show_typing_indicators=excluded.show_typing_indicators;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.publish_safe_profile_presence() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER publish_safe_profile_presence AFTER INSERT OR UPDATE OF is_online,last_seen,show_online_status,show_last_seen,show_read_receipts,show_typing_indicators
ON public.profiles FOR EACH ROW EXECUTE FUNCTION private.publish_safe_profile_presence();
INSERT INTO public.profile_presence(id,is_online,last_seen,show_online_status,show_last_seen,show_read_receipts,show_typing_indicators)
 SELECT id,coalesce(is_online,false) AND coalesce(show_online_status,true),
 CASE WHEN show_last_seen IS DISTINCT FROM false THEN last_seen ELSE NULL END,
 coalesce(show_online_status,true),coalesce(show_last_seen,true),coalesce(show_read_receipts,true),coalesce(show_typing_indicators,true)
 FROM public.profiles;
ALTER PUBLICATION supabase_realtime ADD TABLE public.profile_presence;

CREATE OR REPLACE FUNCTION public.get_public_profiles_by_ids(p_ids uuid[])
RETURNS TABLE(id uuid,display_name text,username text,avatar_url text,bio text,level text,is_online boolean,last_seen timestamptz,status_message text)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT p.id,p.display_name,p.username,p.avatar_url,p.bio,p.level,p.is_online,p.last_seen,p.status_message
 FROM public.public_profiles p WHERE p.id=ANY(p_ids);
$$;
NOTIFY pgrst,'reload schema';

-- Moderators act through a narrow checked endpoint, never a general profile write.
CREATE FUNCTION public.update_profile_moderation(p_target uuid,p_patch jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v public.profiles%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'moderator')) THEN
   RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
 END IF;
 IF NOT public.has_role(auth.uid(),'admin') AND public.has_role(p_target,'admin') THEN
   RAISE EXCEPTION 'Administrator account protected' USING ERRCODE='42501';
 END IF;
 IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR EXISTS (
   SELECT 1 FROM jsonb_object_keys(p_patch) k WHERE k NOT IN ('account_status','suspended_until','suspension_reason')
 ) THEN RAISE EXCEPTION 'Invalid moderation fields'; END IF;
 v:=jsonb_populate_record(NULL::public.profiles,p_patch);
 UPDATE public.profiles p SET
 account_status=coalesce(v.account_status,p.account_status),
 suspended_until=CASE WHEN p_patch?'suspended_until' THEN v.suspended_until ELSE p.suspended_until END,
 suspension_reason=CASE WHEN p_patch?'suspension_reason' THEN v.suspension_reason ELSE p.suspension_reason END
 WHERE p.id=p_target;
END $$;
REVOKE ALL ON FUNCTION public.update_profile_moderation(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_profile_moderation(uuid,jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';

ALTER POLICY "Authenticated users can view all profiles" ON public.profiles
 USING ((select auth.uid())=id OR public.has_role((select auth.uid()),'admin'));
ALTER POLICY "Authenticated users can view all profiles" ON public.profiles
 RENAME TO "Owners and administrators read full profiles";
ALTER POLICY "Users can update own profile" ON public.profiles
 USING ((select auth.uid())=id) WITH CHECK ((select auth.uid())=id);

CREATE OR REPLACE FUNCTION public.generate_afroloc_code(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cc text; v_lat double precision; v_lng double precision;
  v_city text; v_nb text; v_prov text; v_mun text; v_com text;
begin
  if coalesce(auth.jwt()->>'role','') <> 'service_role'
     and (auth.uid() is null or (auth.uid() <> p_user_id and not public.has_role(auth.uid(),'admin'))) then
    raise exception 'Private location access denied' using errcode='42501';
  end if;
  select upper(country_code), latitude, longitude, city, neighborhood
    into v_cc, v_lat, v_lng, v_city, v_nb
    from public.profiles where id = p_user_id;
  if v_lat is null or v_lng is null then return null; end if;
  if v_cc = 'AO' and v_city is not null and v_nb is not null then
    select prov_seg, mun_slug, com_slug into v_prov, v_mun, v_com
      from public.afroloc_banda_division
     where country_code='AO' and lower(city)=lower(v_city) and banda_norm=lower(btrim(v_nb)) limit 1;
  end if;
  return public.afroloc_nom(coalesce(v_cc,'AO'), v_prov, v_mun, v_com, v_lat, v_lng);
end;
$function$;
